import { test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { mkdtempSync, writeFileSync, copyFileSync, mkdirSync, rmSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";

// runCheck tracks one generated file in a scratch repository, lets setup add
// its sources, and returns the checker's exit code and output.
const runCheck = (file, header, setup) => {
  const root = mkdtempSync(join(tmpdir(), "marker-test-"));
  try {
    copyFileSync(new URL("./check-codex-markers.mjs", import.meta.url), join(root, "check.mjs"));
    mkdirSync(join(root, "bin"));
    writeFileSync(join(root, "bin/git"), `#!/bin/sh\nprintf '${file}\\0'\n`, { mode: 0o755 });
    writeFileSync(join(root, file), header);
    setup(root);
    try {
      const output = execFileSync(process.execPath, [join(root, "check.mjs")], {
        cwd: root,
        env: { ...process.env, PATH: `${join(root, "bin")}:${process.env.PATH}` },
        encoding: "utf8",
        stdio: ["ignore", "pipe", "pipe"],
      });
      return { code: 0, output };
    } catch (error) {
      return { code: error.status, output: String(error.stdout) + String(error.stderr) };
    }
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
};

for (const marker of [
  "Generated by engine-sync from source.md — edit the source, then run: engine-sync build",
  "Generated by pfm codex build from source.md; do not edit",
]) {
  for (const live of [true, false]) {
    test(`${marker}: source ${live ? "live" : "missing"}`, () => {
      const { code, output } = runCheck("mirror.md", `<!-- ${marker} -->\n`, (root) => {
        if (live) writeFileSync(join(root, "source.md"), "source\n");
      });
      assert.equal(code, live ? 0 : 1, output);
      if (!live) assert.match(output, /mirror\.md.*source\.md/);
    });
  }
}

// The OpenCode config names its writer and an optional co-source: with no
// .mcp.json the writer alone keeps the file live.
test("engine-sync opencode build + .mcp.json: writer only", () => {
  const header =
    "// Generated by engine-sync from engine-sync opencode build + .mcp.json — edit the source, then run: engine-sync build\n{}\n";
  const { code, output } = runCheck("opencode.jsonc", header, () => {});
  assert.equal(code, 0, output);
});
